#!/bin/bash
sed -i 's/val request = OneTimeWorkRequestBuilder<ChapterDownloadWorker>()/val type = _item.value?.type\n                val workerClass = if (type == com.example.data.models.ContentType.ANIME || type == com.example.data.models.ContentType.DRAMA) {\n                    com.example.workers.VideoDownloadWorker::class.java\n                } else {\n                    com.example.workers.ChapterDownloadWorker::class.java\n                }\n                val request = OneTimeWorkRequestBuilder<androidx.work.CoroutineWorker>().apply { setWorkerClass(workerClass) }/g' app/src/main/java/com/example/ui/viewmodels/DetailViewModel.kt
sed -i 's/putString("mangaId", itemId)/putString("mangaId", itemId).putString("animeId", itemId).putString("episodeId", chapterId)/g' app/src/main/java/com/example/ui/viewmodels/DetailViewModel.kt
